/* Rule entries converted from the 16 Nov 2026 research pass. status: verified = official PDF text read; web = official web page read through a summariser; unverified = clause not seen. */
window.BPDATA.entries.push.apply(window.BPDATA.entries,[{"id":"rule-AD-01","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Headroom","body":"Headroom of every room, access route and circulation space ≥ 2.0 m, measured FFL to underside of beam/duct/pipe/fitting; at doorway to underside of transom","evidence":"Sections with clear-height dimensions under beams and services; door schedule heights","ref":"Approved Document V7.08 (Oct 2025), C.3.2.1 + Notes","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-02","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Headroom, car park","body":"Sheltered car parks: headroom at parking lots and driveway ≥ 2.2 m","evidence":"Car park sections showing clear height under lowest service","ref":"Approved Document V7.08 (Oct 2025), C.3.2.2","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-03","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Ceiling height","body":"Ceiling height of rooms and spaces ≥ 2.4 m (FFL to underside of slab or false ceiling, whichever lower). Not required for corridors, lobbies, toilets/bathrooms, localised drops under beams/services","evidence":"Sections and RCPs with ceiling levels","ref":"Approved Document V7.08 (Oct 2025), C.3.3.1; C.2.3","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-04","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Headroom exemptions","body":"C.2.1 not applicable to: attic ≤ 10 m² in owner-occupied house; plant rooms; under-stair not on a route; toilets in owner-built house; store room ≤ 6 m²","evidence":"Room labels and areas","ref":"Approved Document V7.08 (Oct 2025), C.2.2","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-05","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Stair width","body":"Clear width of every staircase ≥ 1000 mm; handrail may project ≤ 80 mm each side without deduction","evidence":"Stair plan with clear width between walls/balustrades","ref":"Approved Document V7.08 (Oct 2025), E.3.3.1 + Note","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-06","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Riser","body":"Riser height ≤ 175 mm","evidence":"Stair section: riser count × height = floor-to-floor","ref":"Approved Document V7.08 (Oct 2025), E.3.4.1","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-07","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Tread","body":"Tread ≥ 225 mm (stair inside a residential unit); ≥ 250 mm (industrial building); ≥ 275 mm (all other, incl. residential common stairs)","evidence":"Stair section/detail tread dimension","ref":"Approved Document V7.08 (Oct 2025), E.3.4.2","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-08","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Tapered treads, uniformity","body":"Tapered-step tread measured 500 mm from narrow end; risers and treads uniform within a flight (5 mm tolerance between consecutive steps)","evidence":"Winder detail; stair setting-out","ref":"Approved Document V7.08 (Oct 2025), E.3.4.3–E.3.4.4","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-09","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Landings","body":"Landing at every floor level and door opening; intermediate landing at intervals ≤ 18 risers (except spiral)","evidence":"Riser count per flight on stair plan","ref":"Approved Document V7.08 (Oct 2025), E.3.5.1–E.3.5.2","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-10","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Landing width, winders","body":"Landing clear width ≥ 1000 mm; no step or drop in a landing; winders only inside a residential unit, max 1 winder per 90° turn with ≥ 1 tread between","evidence":"Stair plan","ref":"Approved Document V7.08 (Oct 2025), E.3.5.3–E.3.5.4","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-11","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Stair headroom / projections","body":"No projection (other than handrails) into stair space within 2.0 m above landing or pitch line","evidence":"Stair section with 2.0 m clearance line","ref":"Approved Document V7.08 (Oct 2025), E.3.2.1","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-12","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Handrail provision and height","body":"Handrail on at least one side of any flight with more than 5 steps; top of handrail 800–1000 mm above pitch line; continuous over full stair length","evidence":"Stair section/detail","ref":"Approved Document V7.08 (Oct 2025), E.3.6.1, E.3.6.2, E.3.6.5","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-13","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Handrail profile","body":"Circular section 32–50 mm diameter; clear space to wall ≥ 40 mm (≥ 60 mm rough wall); recess to extend ≥ 450 mm above rail","evidence":"Handrail detail","ref":"Approved Document V7.08 (Oct 2025), E.3.6.3–E.3.6.4","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-14","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Stair nosing","body":"Nosing not to project beyond riser face; riser splay ≤ 25 mm; contrasting nosing strips 50–75 mm wide (painting not accepted). Not applicable inside residential units","evidence":"Stair detail, finishes schedule","ref":"Approved Document V7.08 (Oct 2025), E.3.7.1–E.3.7.4","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-15","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Stair edge barrier","body":"Barrier required on any open side of a staircase with a drop ≥ 1000 mm","evidence":"Stair section/elevation","ref":"Approved Document V7.08 (Oct 2025), E.2.2(e)","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-16","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Natural lighting","body":"Windows/openings with aggregate light-transmitting area ≥ 10 % of floor area of the room. Mandatory natural lighting for residential (except toilets, stores, basement, CD shelter)","evidence":"Window schedule vs room area table","ref":"Approved Document V7.08 (Oct 2025), F.3.2.1; F.2.2–F.2.3","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-17","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Natural ventilation","body":"Openable windows/openings with aggregate effective open area ≥ 5 % of floor area. Fixed louvres count at 50 % of opening area; restricted windows = width × height × sin θ","evidence":"Window schedule (openable area) vs room area","ref":"Approved Document V7.08 (Oct 2025), G.3.2.1 + Note","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-18","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Ventilation opening must face","body":"Exterior, or airwell min width 3.0 m and min area 10 m² (height ≤ 30 m) + 1 m² per additional 3 m of height or part, or a recess > 3.0 m deep with min width 3.0 m","evidence":"Airwell dimensions on plans; airwell height on section","ref":"Approved Document V7.08 (Oct 2025), G.3.2.2; Table G.3.2.2(a)","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-19","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Depth of naturally ventilated room","body":"No part of a naturally ventilated room (except warehouse) more than 12 m from a ventilating window/opening","evidence":"Plan dimension from farthest point to opening","ref":"Approved Document V7.08 (Oct 2025), G.3.2.3","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-20","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Ventilation exemptions","body":"No ventilation required for store room, private lift lobby, walk-in wardrobe each ≤ 6 m². Residential must be naturally ventilated except fitness room, clubhouse, CD shelter, toilets, basement (MV allowed)","evidence":"Room labels, areas, MV notes","ref":"Approved Document V7.08 (Oct 2025), G.2.2–G.2.4","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-21","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Barrier trigger","body":"Barrier required where vertical drop ≥ 1.0 m (not for inaccessible roofs, loading docks, stages etc.)","evidence":"Sections showing level differences","ref":"Approved Document V7.08 (Oct 2025), H.2.1–H.2.2","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-22","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Barrier height","body":"≥ 1.0 m; ≥ 900 mm at lower edge of window, and at gallery/balcony with fixed seating. Height measured from top of any kerb/flat surface > 150 × 150 mm next to barrier; such kerb must otherwise be ≥ 1000 mm below barrier top","evidence":"Parapet/railing/window sill details with heights from FFL and from kerb","ref":"Approved Document V7.08 (Oct 2025), H.3.2.1 + Notes","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-23","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Barrier openings","body":"No gap from FFL up to 75 mm at base; lowest 75 mm of bay window not openable; gaps must not pass a 100 mm sphere (non-industrial), 150 mm (industrial), 500 mm (maintenance areas for authorised persons)","evidence":"Railing detail: baluster spacing, bottom gap","ref":"Approved Document V7.08 (Oct 2025), H.3.4.1–H.3.4.3","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-24","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Stair openings","body":"Gap between consecutive steps: must not pass 100 mm sphere (150 mm industrial); triangular void at tread/riser/barrier must not pass 150 mm sphere (non-industrial)","evidence":"Open-riser stair detail","ref":"Approved Document V7.08 (Oct 2025), H.3.4.4","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-25","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Climbability","body":"Barrier height ≥ H.3.2.1 value or 850 mm above the last climbable toehold, whichever higher. Toehold = opening > 50 mm wide and > 30 mm high in mesh/perforated sheet, or kerb/protrusion > 50 mm wide with chamfer gentler than 45°. Climbable if within 600 mm of FFL, a step or another climbable toehold. Not applicable to industrial buildings, bay windows, owner-built houses","evidence":"Railing elevation: horizontal members, mesh size, kerbs","ref":"Approved Document V7.08 (Oct 2025), H.3.4A.1; H.2.5","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-26","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Glass barriers","body":"Laminated glass mandatory where glass forms part or whole of a barrier; comply SS 341; design to BS 6180 Section 8; loading to SS EN 1991-1-1","evidence":"Glass type annotation in barrier detail","ref":"Approved Document V7.08 (Oct 2025), H.3.3.1–H.3.3.2; H.3.5","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-27","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Lift requirement","body":"Building of 5 or more storeys (including ground and any basement level) must have at least one passenger lift","evidence":"Storey count on section; lift on plans","ref":"Approved Document V7.08 (Oct 2025), K.2.1","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-28","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Lightning protection","body":"LPS to SS 555 Parts 1–3, minimum Class III","evidence":"Roof plan/LPS note (usually M&E)","ref":"Approved Document V7.08 (Oct 2025), L.3.1","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-29","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Glass at height","body":"Glass in facade/roof/canopy/overhead glazing at ≥ 2.4 m height: use annealed, heat-strengthened or laminated glass; monolithic tempered or heat-soaked tempered only with screens/shields; SS 341","evidence":"Glazing schedule with glass type and height","ref":"Approved Document V7.08 (Oct 2025), N.2.1; N.3.2–N.3.4","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-30","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Structural sealant glazing","body":"SSG at ≥ 2.4 m: two-sided, or four-sided with retaining devices; mechanical self-weight support to all panels","evidence":"Curtain wall detail","ref":"Approved Document V7.08 (Oct 2025), N.3.6–N.3.7","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-31","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Daylight reflectance","body":"Glass daylight reflectance ≤ 20 %; other facade materials specular reflectance ≤ 10 %; roof ≤ 20° pitch: specular ≤ 10 %; roof > 20° pitch: daylight ≤ 20 % and specular ≤ 10 %; emulsion paint specular ≤ 10 %","evidence":"Material schedule/facade notes","ref":"Approved Document V7.08 (Oct 2025), P.3.2","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-32","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Roof separation (landed)","body":"Semi-detached/terrace/linked houses: party wall extended above roof level so each roof is separate and independent","evidence":"Roof plan and party wall section","ref":"Approved Document V7.08 (Oct 2025), J.3.1","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-33","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Vehicle barriers","body":"Barriers at perimeter of floors with vehicular access and at pedestrian areas near vehicles; resist SS EN 1991 forces","evidence":"Car park plan: barrier/bollard locations","ref":"Approved Document V7.08 (Oct 2025), O.2.1–O.3.2","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-34","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Energy efficiency","body":"Section I of the AD is deleted; envelope limits now sit in the ES Code (see ES-02 to ES-04)","evidence":"n/a","ref":"Approved Document V7.08 (Oct 2025), Section I note","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-AD-35","kind":"rule","scope":"bca","agency":"BCA","topic":"Approved Document V7.08 (Oct 2025)","status":"verified","title":"Wet areas / roof access","body":"Gap: AD V7.08 contains no section on wet-area waterproofing or roof access (sections run A–P). No rule recorded","evidence":"n/a","ref":"Approved Document V7.08 (Oct 2025), –","src":"https://isomer-user-content.by.gov.sg/338/9b829cff-5743-47b1-8fbf-b4c8f426d6df/approved-document-v7-07.pdf"},
{"id":"rule-ES-01","kind":"rule","scope":"bca","agency":"BCA","topic":"ES Code 4th Ed.","status":"unverified","title":"ES Code applicability","body":"Code 4th ed. scope clause: building works with GFA ≥ 5,000 m²; extensions adding ≥ 5,000 m²; major retrofit of existing buildings with GFA ≥ 5,000 m². Conflict to resolve: BCA's web page lists a 2,000 m² threshold for submissions from 1 Dec 2021; the governing Regulations (S 199/2008, reg 3, amended 2021 and 2025) could not be opened (SSO returned 403)","evidence":"GFA table","ref":"ES Code 4th Ed., ES Code s.1 (Scope)","src":"https://isomer-user-content.by.gov.sg/338/e10c055b-7b54-4405-852b-fa3f661af697/es-code_reg-2008_edition-4-0.pdf"},
{"id":"rule-ES-02","kind":"rule","scope":"bca","agency":"BCA","topic":"ES Code 4th Ed.","status":"verified","title":"ETTV","body":"Non-residential envelope ETTV ≤ 45 W/m² (40 W/m² appears only as an optional carbon-reduction measure)","evidence":"ETTV calculation; facade WWR, glass spec","ref":"ES Code 4th Ed., NRB01-1","src":"https://isomer-user-content.by.gov.sg/338/e10c055b-7b54-4405-852b-fa3f661af697/es-code_reg-2008_edition-4-0.pdf"},
{"id":"rule-ES-03","kind":"rule","scope":"bca","agency":"BCA","topic":"ES Code 4th Ed.","status":"verified","title":"RETV","body":"Residential envelope RETV ≤ 22 W/m² (20 W/m² optional measure)","evidence":"RETV calculation","ref":"ES Code 4th Ed., RB01-1","src":"https://isomer-user-content.by.gov.sg/338/e10c055b-7b54-4405-852b-fa3f661af697/es-code_reg-2008_edition-4-0.pdf"},
{"id":"rule-ES-04","kind":"rule","scope":"bca","agency":"BCA","topic":"ES Code 4th Ed.","status":"verified","title":"RTTV","body":"Roofs with skylights: RTTV ≤ 50 W/m²; roofs without skylight: U-value limits by weight group (values not extracted)","evidence":"Roof build-up section","ref":"ES Code 4th Ed., NRB01-2 / RB01-2","src":"https://isomer-user-content.by.gov.sg/338/e10c055b-7b54-4405-852b-fa3f661af697/es-code_reg-2008_edition-4-0.pdf"},
{"id":"rule-ES-05","kind":"rule","scope":"bca","agency":"BCA","topic":"ES Code 4th Ed.","status":"verified","title":"Minimum Green Mark score","body":"Base requirements plus carbon-reduction measures to reach minimum Green Mark score of 50 points","evidence":"n/a (calculation)","ref":"ES Code 4th Ed., s.3.4.1","src":"https://isomer-user-content.by.gov.sg/338/e10c055b-7b54-4405-852b-fa3f661af697/es-code_reg-2008_edition-4-0.pdf"},
{"id":"rule-BD-01","kind":"rule","scope":"bca","agency":"BCA","topic":"Buildability COP 2022","status":"verified","title":"Buildability applicability","body":"Minimum Buildable Design Score and Constructability Score apply to new building works with GFA ≥ 5,000 m², and A&A with new/reconstructed floor GFA ≥ 5,000 m²","evidence":"GFA table","ref":"Buildability COP 2022, 5.2.1–5.2.2; 7.2.1–7.2.2","src":"https://isomer-user-content.by.gov.sg/338/7aecf16a-f0bf-4eca-8735-dd9c81b4510a/cop-on-buildability-20220f6b47e85361460a975ce6e3b54156ac.pdf"},
{"id":"rule-BD-02","kind":"rule","scope":"bca","agency":"BCA","topic":"Buildability COP 2022","status":"verified","title":"Min B-Score (superstructure)","body":"Planning submissions on/after 30 Apr 2022. 5,000 ≤ GFA < 25,000 m² / GFA ≥ 25,000 m²: Public residential 68/80; Private residential 68/80; Commercial 60/70; Industrial 65/70; Institutional, school, others 60/66; MRT station 60","evidence":"B-score computation sheets","ref":"Buildability COP 2022, Table C","src":"https://isomer-user-content.by.gov.sg/338/7aecf16a-f0bf-4eca-8735-dd9c81b4510a/cop-on-buildability-20220f6b47e85361460a975ce6e3b54156ac.pdf"},
{"id":"rule-BD-03","kind":"rule","scope":"bca","agency":"BCA","topic":"Buildability COP 2022","status":"verified","title":"Min B-Score (basement)","body":"42 for GFA ≥ 5,000 m² (single merged value across categories as extracted)","evidence":"–","ref":"Buildability COP 2022, Table D","src":"https://isomer-user-content.by.gov.sg/338/7aecf16a-f0bf-4eca-8735-dd9c81b4510a/cop-on-buildability-20220f6b47e85361460a975ce6e3b54156ac.pdf"},
{"id":"rule-BD-04","kind":"rule","scope":"bca","agency":"BCA","topic":"Buildability COP 2022","status":"verified","title":"Min C-Score","body":"Buildings > 6 storeys: 50 (min 35 from structural system) for 5,000 ≤ GFA < 25,000 m²; 60 (min 45 structural) for ≥ 25,000 m². Table K (≤ 6 storeys) not extracted","evidence":"–","ref":"Buildability COP 2022, Table J","src":"https://isomer-user-content.by.gov.sg/338/7aecf16a-f0bf-4eca-8735-dd9c81b4510a/cop-on-buildability-20220f6b47e85361460a975ce6e3b54156ac.pdf"},
{"id":"rule-COA-01","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Scope","body":"All areas/levels to be accessible. Applies to new areas and existing areas with A&A requiring BCA plan approval. Does not apply to landed dwelling-houses. Exempt: plant rooms, loading docks, heavy-machinery production areas, warehousing/storage areas, clean rooms, hazardous process plants","evidence":"Accessibility plan","ref":"Code on Accessibility 2025 v1.1, 2.1.1, 2.1 Note, 2.2.1, 2.5.1","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-02","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Building-type matrix","body":"Table 1 fixes sanitary/family/other provisions by type, with GFA breakpoints: offices 5,000 m² (lactation room); shopping centres 5,000 / 10,000 / 20,000 m²; mixed-development non-residential component ≥ 5,000 m²","evidence":"GFA and use schedule","ref":"Code on Accessibility 2025 v1.1, Table 1","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-03","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Accessible-route plan","body":"A plan showing the primary accessible route, incl. barrier-free links to adjacent buildings and commuter facilities, must be submitted for BP approval","evidence":"Dedicated accessible-route drawing present","ref":"Code on Accessibility 2025 v1.1, 2.4.2","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-04","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Entrances","body":"Main entrance accessible; entrances connecting to adjacent buildings, commuter facilities, park connectors and covered linkways all accessible","evidence":"Site/1st-storey plan","ref":"Code on Accessibility 2025 v1.1, 3.1.1–3.1.2","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-05","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Route width","body":"Primary accessible route ≥ 1500 mm (residential, office, hotel, serviced apartment, hostel, preschool–secondary school, factory/industrial/warehouse, workers' dormitory) or ≥ 1800 mm (all other uses); all other accessible routes ≥ 1200 mm","evidence":"Corridor/path clear widths","ref":"Code on Accessibility 2025 v1.1, 4.2.1.1; Table 3","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-06","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Passing and turning","body":"Where route < 1800 mm: passing space 1800 × 1800 mm at intervals ≤ 25 m. Dead-end corridor: turning space ≥ 2000 mm (direction of travel) × ≥ 1500 mm","evidence":"Corridor plans","ref":"Code on Accessibility 2025 v1.1, 4.2.1.2–4.2.1.3","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-07","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Gantries, checkout","body":"At least one accessible gate/gantry and one checkout lane, each ≥ 900 mm wide","evidence":"Lobby/retail layout","ref":"Code on Accessibility 2025 v1.1, 4.2.2.1–4.2.2.2","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-08","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Headroom on routes","body":"Clear headroom in walkways, halls, corridors, aisles ≥ 2000 mm","evidence":"Sections","ref":"Code on Accessibility 2025 v1.1, 4.3.1","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-09","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Door clear opening","body":"≥ 850 mm, measured door face to doorstop at 90°; for double-leaf doors at least one active leaf to comply","evidence":"Door schedule clear widths","ref":"Code on Accessibility 2025 v1.1, 4.4.2.1; 4.4.3","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-10","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Door manoeuvring space","body":"Pull side: 600 mm beside leading edge + 1500 × 1500 mm clear; push side: 300 mm + 1200 × 1200 mm; two-way swing/sliding: 300 mm + 1200 × 1200 mm both sides. Two doors in series: 1200 mm plus door swing","evidence":"Plans at doors (latch-side clearance)","ref":"Code on Accessibility 2025 v1.1, 4.4.6.1","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-11","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Level changes","body":"Max gradient by rise: 0–15 mm 1:2; > 15–50 mm 1:5; > 50–175 mm 1:10; > 175 mm 1:12","evidence":"Thresholds, level annotations","ref":"Code on Accessibility 2025 v1.1, 4.5.1; Table 4","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-12","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Kerb ramps","body":"For rise ≤ 175 mm: clear width ≥ 900 mm; gradient ≤ 1:10 incl. flared sides","evidence":"External works plan","ref":"Code on Accessibility 2025 v1.1, 4.5.3.1–4.5.3.2","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-13","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Ramp gradient and run","body":"Max run between landings: 1:12 – 6 m; 1:14 – 9 m; 1:16 – 12 m; 1:20 – 15 m; 1:24 – 18 m; 1:25 or gentler – handrails/edge protection non-mandatory","evidence":"Ramp plan/section: gradient, run, landings","ref":"Code on Accessibility 2025 v1.1, 4.6.5.2; Table 5","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-14","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Ramp width and landings","body":"Ramp clear width per Table 3 (may reduce to 1200 mm if adjacent steps provided and total rise ≤ 1200 mm); landings ≥ 1500 mm deep × ramp width","evidence":"Ramp plan","ref":"Code on Accessibility 2025 v1.1, 4.6.3.1 + Note; 4.6.5.2(a)","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-15","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Ramp handrails and edges","body":"Rise > 175 mm: handrails both sides at 800–900 mm, extending ≥ 300 mm beyond run; edge kerb ≥ 75 mm or barrier with lower edge ≤ 75 mm","evidence":"Ramp section/detail","ref":"Code on Accessibility 2025 v1.1, 4.6.6.1; 4.6.7.1","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-16","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Stairs on accessible routes","body":"Handrails 800–1000 mm above pitch line extending ≥ 300 mm beyond top/bottom; nosing strips 50–75 mm; riser splay ≤ 25 mm; warning TGSI 600 mm deep set 300 mm from first step","evidence":"Stair details","ref":"Code on Accessibility 2025 v1.1, 4.7.2–4.7.4","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-17","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Wheelchair lift","body":"Where passenger lifts are provided, at least one accessible to wheelchair users serving all levels; car ≥ 1200 mm wide × 1500 mm deep; clear door opening ≥ 900 mm; lobby clear space 1500 × 1500 or 1800 × 1800 mm per Table 3","evidence":"Lift car and lobby dimensions","ref":"Code on Accessibility 2025 v1.1, 4.8.1.2; 4.9.1.1–4.9.1.3; 4.9.2.1; 4.9.3.1","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-18","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Accessible washroom provision","body":"Where toilets are provided: at least one accessible individual washroom at every toilet cluster (clause note: at least one at every level where toilets are provided). Larger accessible washroom at every level in shopping centres, sports facilities, places of public resort, worship, markets/hawker centres, transport terminals, tertiary institutions, hospitals, polyclinics","evidence":"Toilet layout per storey","ref":"Code on Accessibility 2025 v1.1, 5.1.1; 5.1.3","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-19","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Accessible washroom size","body":"Accessible individual washroom ≥ 1750 × 1750 mm clear internal; larger accessible washroom ≥ 1800 wide × 2100 mm deep; door clear opening ≥ 850 mm; accessible changing room ≥ 2600 mm (second dimension not extracted)","evidence":"Toilet enlarged plans","ref":"Code on Accessibility 2025 v1.1, 5.2.1; 5.3.1; 5.8.1.1","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-20","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Ambulant cubicle","body":"One ambulant-disabled WC cubicle per 4 WC cubicles or part thereof; cubicle min width 900 mm; at least one ambulant urinal where urinals provided","evidence":"Toilet layout","ref":"Code on Accessibility 2025 v1.1, 5.1.5–5.1.6; 5.4.1","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-21","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Accessible WC compartment / shower","body":"Accessible WC compartment ≥ 1500 × 1750 mm; accessible shower ≥ 1500 mm (second dimension not extracted); combined shower-with-WC ≥ 2000 × 1750 mm","evidence":"Toilet/shower enlarged plans","ref":"Code on Accessibility 2025 v1.1, 5.6.1; 5.7.1.1–5.7.1.2","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-22","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Accessible parking number","body":"Lots provided → accessible lots (hospital / other): 1–10: 1/1; 11–50: 2/1; 51–100: 4/2; every subsequent 200 lots or part: +1. Over and above LTA provision","evidence":"Car park lot schedule","ref":"Code on Accessibility 2025 v1.1, 3.3.1.1; Table 2","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-23","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Accessible parking size","body":"4800 × 3600 mm (angled); 5400 × 3600 mm (parallel); 7200 × 3600 mm (parallel where reversing not possible/obstructed ends); vertical sign ≥ 450 × 450 mm, centre ≥ 1500 mm above floor","evidence":"Car park plan lot dimensions","ref":"Code on Accessibility 2025 v1.1, 3.3.2.1","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-24","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Drop-off","body":"At least one sheltered accessible alighting/boarding point; with level difference: access aisle ≥ 1200 × 4500 mm and kerb ramp","evidence":"1st-storey/site plan","ref":"Code on Accessibility 2025 v1.1, 3.2.1; 3.2.4","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-25","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Residential units","body":"At least one accessible entrance per unit: clear width ≥ 850 mm; clear floor space 1250 × 1500 mm at entrance; switches/sockets at 450 mm upward band (upper limit not extracted); scupper drain in corridor ≤ 150 mm wide × 50 mm deep along one side","evidence":"Unit plans, corridor section","ref":"Code on Accessibility 2025 v1.1, 7.1.3; 7.1.5; 7.2.1–7.2.2; 7.4.1","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-26","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Hotel rooms","body":"Accessible guestrooms: additionally at least one per 50 guestrooms or part with specified features; 1500 × 1500 mm clear floor space in room","evidence":"Room schedule","ref":"Code on Accessibility 2025 v1.1, 7.5.3; 7.5.6","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-27","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Family provisions","body":"Lactation room ≥ 1200 × 1500 mm, number per Table 6 by GFA; family car park lot where vehicle parks provided (types per Table 1)","evidence":"Toilet cluster plans","ref":"Code on Accessibility 2025 v1.1, 6.1.2; 6.2.1; 6.8.3–6.8.4","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-COA-28","kind":"rule","scope":"access","agency":"BCA","topic":"Code on Accessibility 2025 v1.1","status":"verified","title":"Gratings, cross-fall","body":"Grating gaps ≤ 12 mm, long dimension perpendicular to travel; drainage cross-fall ≤ 1:40","evidence":"External works details","ref":"Code on Accessibility 2025 v1.1, 4.1.3–4.1.4","src":"https://go.gov.sg/bca-coa2025"},
{"id":"rule-FC-01","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Purpose groups","body":"PG I small residential (detached, semi-D, terrace); II other residential (flats, maisonettes, condos, cluster); III institutional (incl. hospitals, schools, workers' dormitories); IV office; V shop; VI factory; VII place of public resort (incl. hotels, F&B, assembly); VIII storage (incl. warehouses, vehicle parks)","evidence":"Use/PG stated in fire safety plan title block","ref":"Fire Code 2023, Table 1.4A (related tables ch.1) (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-02","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Occupant load factors","body":"m²/person (selected): residential flats/maisonettes 15; hotel/serviced apartment/hostel 15; office 10; shop/supermarket 5; gymnasium 3.5; classroom 1.5; restaurant 1.5; bar/pub 1.0; car park 30; general storage 30. Computed on accessible floor area. Table has been amended several times – confirm full table","evidence":"Occupant load table on plans","ref":"Fire Code 2023, Table 1.4B (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-03","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Habitable height","body":"Measured from lowest fire engine accessway/access road level to FFL of highest habitable floor (roof with only M&E plant is non-habitable). Above 24 m triggers: rising mains, sprinklers*, fire lift/FCC*, voice communication*, alarm, stair pressurisation (*not PG II unless required)","evidence":"Section with accessway level and top habitable FFL","ref":"Fire Code 2023, Cl. 1.4.64–1.4.65 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-04","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Travel distance – offices","body":"One-way 15 m (non-sprinklered) / 30 m (sprinklered); two-way 45 / 75 m","evidence":"Travel distance lines on fire plan","ref":"Fire Code 2023, Table 2.2A (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-05","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Travel distance – shops, outpatient, public resort, car parks, schools","body":"One-way 15 / 25 m; two-way 45 / 60 m","evidence":"as above","ref":"Fire Code 2023, Table 2.2A (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-06","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Travel distance – factories, warehouses","body":"One-way 15 / 25 m; two-way 30 / 60 m","evidence":"as above","ref":"Fire Code 2023, Table 2.2A; Cl. 2.2.2 text confirms 30/60 two-way (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-07","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Travel distance – high hazard","body":"One-way 10 / 20 m; two-way 20 / 35 m","evidence":"as above","ref":"Fire Code 2023, Table 2.2A (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-08","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Travel distance – hotels, hostels, dormitories, serviced apartments","body":"One-way 15 / 20 m; two-way 30 / 60 m","evidence":"as above","ref":"Fire Code 2023, Table 2.2A (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-09","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Travel distance – inpatient healthcare","body":"One-way 15 / 25 m; two-way 30 / 45 m","evidence":"as above","ref":"Fire Code 2023, Table 2.2A (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-10","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"unverified","title":"Travel distance – flats/maisonettes","body":"Row returned as 15(g) / 20(j) / 30(g) / 40(j) / 30 / 45(j) / 75 – footnote (j) = external corridor, (g) = single-stair flats, (k) measured from unit door. Within unit ≤ 20 m to entrance door (else second door). External corridor one-way 20 m (24 m if unit + corridor ≤ 40 m), two-way up to 45 m. Cell-to-column mapping of the table row not resolved","evidence":"Unit plans with internal travel line; corridor distances","ref":"Fire Code 2023, Table 2.2A; Cl. 9.2.1a.(5), (8)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-11","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Direct distance","body":"In undivided floors, direct distance ≤ 2/3 of permitted travel distance; remote point taken 400 mm off walls","evidence":"Fire plan for shell/open-plan floors","ref":"Fire Code 2023, Cl. 2.2.6 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-12","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Dead end","body":"Max dead end 15 m (non-sprinklered) / 20 m (sprinklered) for all listed occupancies","evidence":"Corridor plans","ref":"Fire Code 2023, Table 2.2A (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-13","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Exit capacity","body":"Unit of width = 500 mm. Persons per unit (door to outside / other doors / stairs / ramps-corridors): office, shop, factory, public resort, school 100/80/60/100; high hazard 50/40/30/50; hotel/dormitory 60/50/45/50; inpatient 30/30/15/30; flats 50/40/30/50. 1000–1249 mm = 2 units; 1250–1499 = 2.5; 1500–1749 = 3; 1750–1999 = 3.5; 2000 = 4 (max per stair)","evidence":"Exit capacity calculation table","ref":"Fire Code 2023, Table 2.2A; Cl. 2.2.5, 2.2.8 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-14","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Minimum widths","body":"Exit staircase ≥ 1000 mm; corridor ≥ 1200 mm (classroom corridors 1.5 m, patient corridors 2 m); exit door/exit access opening ≥ 850 mm clear; PG I dwelling corridor/stair and maisonette internal stair ≥ 900 mm; room ≤ 2 persons door ≥ 610 mm; single leaf ≤ 1250 mm","evidence":"Door schedule, stair/corridor widths","ref":"Fire Code 2023, Cl. 2.2.7; Table 2.2A notes (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-15","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Stairs wider than 2 m","body":"Stair wider than 2 m needs handrails dividing into 1–2 m sections; only 4 units count unless Cl. 2.2.8b conditions met","evidence":"Stair plan","ref":"Fire Code 2023, Cl. 2.2.8 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-16","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Number of exits – rooms","body":"Two remote doors required once room occupant load exceeds: high hazard 25; patient accommodation, classrooms, godowns/stores/non-high-hazard factories, assembly 50","evidence":"Room occupant load + door count","ref":"Fire Code 2023, Cl. 2.2.10; Table 2.2.10 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-17","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Number of exits – storeys","body":"At least 2 independent exit staircases/exits per storey (unless single-exit provisions apply); non-habitable roof 1; access hatch min 1 m clear diameter","evidence":"Each floor plan","ref":"Fire Code 2023, Cl. 2.2.11 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-18","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Remoteness of exits","body":"Exits separated by ≥ 1/2 of max diagonal (1/3 if sprinklered), never < 7 m; scissor stair doors ≥ 7 m apart","evidence":"Diagonal and exit-separation dimension on plan","ref":"Fire Code 2023, Cl. 2.3.12; 2.3.4 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-19","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Exit stair geometry","body":"Riser ≤ 175 mm; tread ≥ 225 mm (in residential units), 275 mm (residential common areas), 250 mm (PG VI and VIII), 275 mm (others); headroom ≥ 2 m; landings ≥ stair width; handrails both sides (one side if ≤ 1.25 m wide)","evidence":"Stair sections","ref":"Fire Code 2023, Cl. 2.3.3d.(3)–(6) (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-20","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Exit stair ventilation","body":"Fixed openings ≥ 10 % of stair floor area per floor on external wall, or MV/pressurisation; internal unventilated stairs pressurised where habitable height > 24 m; PG II stairs naturally ventilated (storey-shelter stair excepted)","evidence":"Stair vent openings on elevations","ref":"Fire Code 2023, Cl. 2.3.3d.(7)–(9); 9.2.1a.(10) (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-21","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Openings near stairs/discharge","body":"No unprotected openings within 1.5 m horizontally / 3 m vertically below internal stair openings; within 3 m of external stair; within 3 m of discharge point (1.5 m if same plane); max 2 exit doors into a stair shaft per storey","evidence":"Elevations near stair cores","ref":"Fire Code 2023, Cl. 2.3.3a–c (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-22","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Smoke-stop / fire lift lobby","body":"Smoke-stop lobby ≥ 3 m², clear width ≥ 1.2 m; fire lift lobby ≥ 6 m², clear width ≥ 2 m; natural vent openings ≥ 15 % of lobby floor area (each ≥ 1 m²), no part > 9 m from opening; smoke-free approach required for buildings over 4 storeys","evidence":"Lobby dimensions and openings","ref":"Fire Code 2023, Cl. 2.2.13 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-23","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Basement lobbies","body":"1 basement: none; 2–4 basements: at least one stair per level via smoke-free lobby (doubling as fire lift lobby); > 4 basements: all stairs via lobbies","evidence":"Basement plans","ref":"Fire Code 2023, Cl. 2.2.14 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-24","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"External corridor","body":"Vent opening ≥ 1.2 m high above parapet; roofed depth ≤ 3 m; parapet 1.0–1.5 m high; airwell for smoke-free lobbies/external corridors ≥ 93 m² and ≥ 6 m wide","evidence":"Corridor section; airwell dims","ref":"Fire Code 2023, Cl. 2.3.10–2.3.11 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-25","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Exit ramps, spiral stairs","body":"Exit ramp ≤ 1:10 (curved ≤ 1:12); spiral exit stair: external, tread length ≥ 750 mm, ≤ 10 m high, ≤ 25 persons","evidence":"Ramp/stair details","ref":"Fire Code 2023, Cl. 2.3.7–2.3.8 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-26","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Area of refuge","body":"0.3 m² per person","evidence":"Refuge floor plan","ref":"Fire Code 2023, Cl. 2.2.15; 2.2.6(e) (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-27","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Compartment size","body":"Below ground: 2,000 m² / 7,500 m³, 1 storey per compartment; ground to 24 m: 4,000 m² / 15,000 m³, max 3 storeys; above 24 m: 2,000 m² / 7,500 m³, 1 storey (residential maisonette/penthouse 2). Exceeding → sprinklers","evidence":"Compartment area table; compartment lines","ref":"Fire Code 2023, Table 3.2A; Cl. 3.2.1, 3.2.4; 6.4.1a (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-28","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Special compartments","body":"Different PGs separated ≥ 1 hr; open-flame kitchen 1 hr with ½-hr door (non-sprinklered ≤ 150 m²); store > 10 m² in non-sprinklered building 1 hr; FCC 2 hr; plant/transformer/generator rooms 2 hr (1 hr if sprinklered); vehicle workshop 2 hr (4 hr basement)","evidence":"Wall ratings on fire plan","ref":"Fire Code 2023, Cl. 3.2.5 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-29","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Element fire resistance","body":"Table 3.3A by PG, height (15 m / 28 m / no limit), floor area and cubical extent: generally 1 hr (low/small), 2 hr (tall or large), basements 1–4 hr; PG VIII up to 4 hr. PG I ≤ 3 storeys: 1 hr. Row/column alignment partly lost in extraction – read the table before coding","evidence":"Structural fire-rating notes","ref":"Fire Code 2023, Table 3.3A (related tables ch.3) (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-30","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"PG II unit separation","body":"Each unit compartmented ≥ 1 hr; unit entrance door ½ hr; above 24 m: 1.5 m high 1-hr spandrel or 600 mm horizontal projection between units","evidence":"Unit boundary walls, facade section","ref":"Fire Code 2023, Cl. 9.2.1b (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-31","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"PG II single staircase","body":"≤ 24 m habitable height: one stair allowed if one-way travel met. > 24 m: only if habitable height ≤ 60 m, ≤ 4 units per storey, most remote unit door ≤ 15 m from stair, cross-ventilated lobby openings ≥ 2 m wide × 1.2 m high; maisonette upper storey ≤ 60 m²","evidence":"Typical floor plan","ref":"Fire Code 2023, Cl. 9.2.1a.(3)–(5) (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-32","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Fire engine access – when","body":"PG I/II ≤ 10 m: access road within 60 m of every point of plan area. PG II > 10 m: accessway ≥ 1/4 perimeter (min 15 m) per block and within 18 m of stairs with landing valves. PG III/IV/V/VII ≤ 10 m: access road within 45 m. PG VI/VIII: accessway at all heights","evidence":"Site plan: accessway hatch, distances","ref":"Fire Code 2023, Cl. 4.2.2a (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-33","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Accessway length","body":"PG III/IV/V/VII > 10 m by largest floor AFA (non-sprinklered / sprinklered): ≤ 2,000 m²: 1/6 (min 15 m) both; 2,000–4,000: 1/4, 1/4; 4,000–8,000: 1/2, 1/4; 8,000–16,000: 3/4, 1/2; 16,000–32,000: island site, 3/4; > 32,000: island site. PG VI/VIII by cubical extent starting ≤ 28,400 m³: 1/6 (min 15 m) – sprinklered column for this table incomplete in extract","evidence":"Perimeter calculation on site plan","ref":"Fire Code 2023, Cl. 4.2.2a.(6)–(7) (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-34","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Accessway geometry","body":"Access road ≥ 4 m wide; accessway ≥ 6 m wide (habitable height ≤ 50 m) / 7 m (> 50 m), ≥ 15 m long; 2–10 m from access openings (to 13 m if openings ≤ 20 m high); gradient ≤ 1:15 (access road ≤ 1:8.3); dead end ≤ 46 m; overhead clearance ≥ 4.5 m; loading 24 t / 30 t / 50 t","evidence":"Site plan dims, gradient, turning radii (Diagram 4.2.2e)","ref":"Fire Code 2023, Cl. 4.2.2b–f; Tables 4.2A–4.2C (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-35","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Fire access openings","body":"≥ 850 mm wide × 1000 mm high; sill ≤ 1.1 m; head ≥ 1.8 m above FFL; ≤ 20 m apart c/c along accessway; PG III–VII > 10 m: every storey except 1st, up to 90 m; not required for PG I/II","evidence":"Elevations with access panels marked","ref":"Fire Code 2023, Cl. 4.2.3 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-36","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Rising mains","body":"Dry riser: PG II–VIII habitable height > 10 m and ≤ 60 m, and all basements (except PG I); wet riser > 60 m; every part of floor within 38 m of a landing valve; breeching inlet within 18 m of accessway/access road","evidence":"Riser/landing valve positions on plans","ref":"Fire Code 2023, Cl. 6.2.1–6.2.3 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-37","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Hose reels","body":"Required on every storey of every building (exemptions e.g. non-residential unit AFA ≤ 150 m², open shed ≤ 200 m²); 36 m coverage figure stated for mezzanines (30 m hose + 6 m throw)","evidence":"Hose reel positions","ref":"Fire Code 2023, Cl. 6.2.8 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-38","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Sprinklers – when","body":"Where Table 3.2A limits cannot be met; every storey of buildings > 24 m habitable height (except PG I/II); all basements (except PG I/II use, or cross-ventilated; residential single-level basement car park exempt if openings ≥ 20 % of floor area); atrium ≤ 18 m","evidence":"Sprinkler note; height on section","ref":"Fire Code 2023, Cl. 6.4.1 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-39","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Fire lift","body":"> 24 m habitable height: ≥ 2 fire lifts (non-PG I/II), ≥ 1 for PG II (≥ 2 if over 40 storeys); basement deeper than 9 m: ≥ 2; lift door to exit stair door ≤ 5 m; any part of storey within 60 m of a fire lift","evidence":"Core plans, basement depth on section","ref":"Fire Code 2023, Cl. 6.6.4 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-40","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Evacuation lift","body":"Required (non-PG I/II) where > 24 m or building accessible to PWDs; car ≥ 1.2 × 1.4 m","evidence":"Lift schedule","ref":"Fire Code 2023, Cl. 6.6.5 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-FC-41","kind":"rule","scope":"fire","agency":"SCDF","topic":"Fire Code 2023","status":"unverified","title":"Minor A&A lodgement","body":"Only works listed in the Schedule to reg 4(4), Fire Safety (Building and Pipeline Fire Safety) Regulations may be lodged. MAA plans must include site/location plan, whole-floor plan with exits and fire protection type, detailed layout, section, partition details; new works in magenta, deletions yellow dotted; 150 × 100 mm blank at top right; QP endorsement in title block. Schedule contents (the actual criteria) not seen – SSO blocked","evidence":"Colour convention, title block","ref":"Fire Code 2023, SCDF MAA page: https://scdf.gov.sg/home/fire-safety/plans-and-consultations/minor-addition-alteration-works","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-URA-01","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"web","title":"GFA definition","body":"GFA computed to the middle of external walls (excl. finishes), to middle of windows/doors, to middle of outermost railing/parapet/curtain wall; party wall thickness within the building included; all strata areas count as GFA; where no wall, to edge of covered area","evidence":"GFA verification plans with GFA line","ref":"URA DC handbook, gross-floor-area/gfa-related-matters/ (read from the official web page; spot-check table values)","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-02","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Bonus GFA cap","body":"Bonus GFA schemes capped at a cumulative 10 % above Master Plan GPR (residential: balcony, conserved bungalow, indoor recreation space, Built Environment Transformation schemes)","evidence":"GFA table split base/bonus","ref":"URA DC handbook, Summary-FC-v2.pdf; GFA handbook landing page","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-03","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"web","title":"Household shelter GFA","body":"Household shelters are included as GFA (exclusions only for HS core in foundation and RC slabs at intermediate/roof level)","evidence":"GFA plans","ref":"URA DC handbook, gross-floor-area/household-shelters/ (read from the official web page; spot-check table values)","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-04","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"web","title":"Sky terrace GFA exemption","body":"Exempt area within 45° line from edge of overhead projection; ≥ 40 % perimeter open (≥ 60 % for predominant sky terrace ≥ 60 % of floor plate); depth ≥ 5.0 m; parapet ≤ 1.3 m counts as open; residual area cap 20 % of floor plate; communal access","evidence":"Sky terrace plan with 45° line","ref":"URA DC handbook, gross-floor-area/sky-terraces/ (read from the official web page; spot-check table values)","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-05","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Landed plot size","body":"Bungalow: 400 m², width 10 m (GCBA: 1,400 m², width 18.5 m, depth 30 m). Semi-detached: 200 m², width 8 m (side-to-side) or 10 m (back-to-back). Terrace I: 150 m²/6 m intermediate, 200 m²/8 m corner. Terrace II: 80 m², 6 m intermediate, 8 m corner","evidence":"Site plan: plot area and width","ref":"URA DC handbook, bungalows/plot-size-width/; Summary-Semi-Detached.pdf; Summary-Terrace.pdf","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-06","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Landed site coverage","body":"Bungalow outside GCBA: max 50 % (sub-control 40 %); within GCBA: max 45 % (sub-control 35 %). Counts footprint and features ≥ 1 m above ground","evidence":"Site coverage calculation plan","ref":"URA DC handbook, bungalows/site-coverage/; Summary-Detached.pdf","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-07","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Landed road buffer","body":"Main building: Cat 1 road 24 m (incl. 5 m green buffer); Cat 2 12 m (5 m green); Cat 3–4 7.5 m (3 m green); Cat 5 7.5 m (no green buffer). Car porch eaves: Cat 3–5 2.4 m; Cat 1–2 protrusion into buffer ≤ 5 m","evidence":"Site plan setback dimensions from road reserve line","ref":"URA DC handbook, Summary-Semi-Detached.pdf; Summary-Terrace.pdf; bungalows/setbacks-from-boundaries/","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-08","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Landed common boundary setback","body":"Main building 2 m; roof eaves 1 m (GCBA or plot abutting GCBA: 3 m and 1.6 m). Terrace: side/rear 2 m main building, 1 m eaves/patio","evidence":"Site plan, roof plan eaves line","ref":"URA DC handbook, same as URA-07","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-09","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Landed appendages into setback","body":"Main roof eaves: 2 m into road buffer, 1 m into common boundary setback; ledges/awnings 1 m / 1 m; sun-shading fins/planters 0.5 m into road buffer, none into common boundary; bay windows none","evidence":"Roof/elevation projections dimensioned","ref":"URA DC handbook, Summary-Semi-Detached.pdf; Summary-Terrace.pdf","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-10","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"web","title":"Envelope control","body":"All landed housing (from 11 May 2015): overall height max 12 m (2-storey areas) and 15.5 m (3-storey areas), measured from external platform level; lift overrun/roof barriers may exceed by ≤ 1 m; attics and mezzanines free within envelope; roof terrace on attic roof ≥ 3 m below envelope top. Envelope diagram (setback/slope geometry) not captured as text","evidence":"Sections with envelope overlay from platform level","ref":"URA DC handbook, bungalows/ec/ (read from the official web page; spot-check table values)","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-11","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"web","title":"Landed basements","body":"Basement with protrusion: within road buffer line and building setback. Fully submerged: up to road reserve line if portion under green buffer is ≥ 2 m below ground; to site boundary outside GCBA (2 m setback in GCBA)","evidence":"Basement plan and section","ref":"URA DC handbook, bungalows/ec/ (read from the official web page; spot-check table values)","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-12","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"web","title":"A&A vs reconstruction (landed)","body":"A&A only if all hold: added GFA ≤ 50 % of approved GFA; external walls removed/replaced ≤ 50 % of approved external walls; structural changes (columns, beams, slabs) ≤ 50 % of existing; no added storey; no change of housing form. Otherwise reconstruction. Retention of non-conforming structure: keep ≥ 25 % of existing floor plate; deficient front setback min 2.4 m","evidence":"A&A calculation sheet; demolition plan","ref":"URA DC handbook, bungalows/aa-landed-housing/ (read from the official web page; spot-check table values)","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-13","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Landed walls and earthworks","body":"Boundary wall ≤ 1.8 m; boundary-cum-retaining wall visible height ≤ 2.8 m; outward retaining wall ≤ 1 m; earthworks not allowed in setback except listed cases; vehicular access ≤ 4 m wide; road buffer area may be 300 mm above adjacent road level where MPL applies","evidence":"External works sections","ref":"URA DC handbook, Summary-Semi-Detached.pdf; Summary-Terrace.pdf","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-14","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Landed access and entrance","body":"One vehicular access per plot; new access points paired unless plot width > 10 m; one main entrance door per house","evidence":"1st-storey plan","ref":"URA DC handbook, same","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-15","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Strata landed","body":"Each strata landed unit min 50 m² ground contact; site coverage 50 % (sub-control 40 %) outside GCBA, 45 % (35 %) within; communal open space minimum – figure not captured","evidence":"Site plan, unit footprints","ref":"URA DC handbook, strata-landed-housing/ landing page; Summary-Strata-Landed-Housing.pdf","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-16","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Flats/condo site area and coverage","body":"Flats min site 1,000 m²; condominiums min 4,000 m²; site coverage max 50 % (structures protruding > 1 m above ground in plan view)","evidence":"Site plan and coverage calc","ref":"URA DC handbook, Summary-FC-v2.pdf","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-17","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Flats/condo height by GPR","body":"GPR 1.4 → 5 storeys; 1.6 → 12; 2.1 → 24; 2.8 → 36; > 2.8 → > 36 (subject to street block/technical height plans)","evidence":"Section storey count","ref":"URA DC handbook, Summary-FC-v2.pdf","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-18","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Flats/condo floor-to-floor","body":"GPR 1.4: 1st storey 5.0 m, top 3.6 m, others 3.6 m. GPR > 1.6 column: 1st 5.0 m, top 5.0 m, others 3.6 m; predominant sky terrace storeys 5.0 m. (Column for GPR 1.6 itself not clear in extract)","evidence":"Section floor-to-floor dims","ref":"URA DC handbook, Summary-FC-v2.pdf","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-19","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"web","title":"Flats/condo road buffer","body":"Cat 1: 30 m (6 storeys and above) / 24 m (up to 5 storeys), 5 m green; Cat 2: 15 / 12 m, 5 m green; Cat 3: 10 / 7.5 m, 3 m green; Cat 4–5 and slip road: 7.5 m, 3 m green","evidence":"Site plan","ref":"URA DC handbook, flats-condominiums/setback/ Table 1 (read from the official web page; spot-check table values)","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-20","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"unverified","title":"Flats/condo common boundary","body":"Setback graded by storey height from 3.0 m to 12.6 m (flats) and 3.0 m to 15.5 m (condos); sample points 5 storeys 3.3 / 4.7 m; 10 storeys 4.8 / 8.7 m; 24 storeys 9.0 / 12.4 m; ≥ 36 storeys 12.6 / 15.5 m. 2 m peripheral planting verge along all common boundaries. Cells for 2–4 storeys were garbled in extraction – read table","evidence":"Site plan","ref":"URA DC handbook, flats-condominiums/setback/ Table 2","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-21","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Dwelling units","body":"Outside Central Area: max DUs = GPR × site area / 85 m² (/100 m² in Maps 2–10 estates); ≥ 20 % of DUs ≥ 100 m² nett and ≤ 20 % of DUs ≤ 50 m²; Central Area ≥ 20 % of DUs ≥ 70 m²; every DU > 35 m² nett","evidence":"Unit schedule","ref":"URA DC handbook, Summary-FC-v2.pdf","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-22","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Flats/condo attic, basement, shops","body":"Attic max height 5 m, max pitch 45° from springing line, not strata-separable; basement protruding > 1.0 m counts as a storey; shops ≤ 0.3 % of GFA","evidence":"Roof section, basement section","ref":"URA DC handbook, Summary-FC-v2.pdf","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-23","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Industrial B1/B2 setbacks","body":"Road buffer: Cat 1 15 m (5 m green); Cat 2 7.5 m (3 m green); Cat 3–5 5 m (3 m green). Common boundary: 4.5 m to non-industrial neighbour; none to industrial neighbour. Floor-to-floor min 4.0 m. NEA nuisance buffer 50 m (B1) / 100 m (B2)","evidence":"Site plan, section","ref":"URA DC handbook, Summary-B1.pdf; Summary-B2.pdf; b1/ and b2/ landing pages","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-24","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Industrial 60/40","body":"Min 60 % of GFA predominant industrial use; max 40 % ancillary (ancillary office, meeting rooms, common areas and secondary uses); applies to whole development and to each strata unit in multi-user developments; min unit size 150 m². No separate sub-cap for ancillary office found on the page (allowable-uses page not read)","evidence":"Use quantum table and colour-coded plans","ref":"URA DC handbook, Summary-B1.pdf; b1/use-quantum/","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-25","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Industrial goods lifts","body":"GFA < 10,000 m²: 1 goods lift + 1 loading bay; 10,000–30,000: 2 + 2; > 30,000: 3 + 3","evidence":"Plans","ref":"URA DC handbook, Summary-B1.pdf","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-26","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"Commercial","body":"Road buffer Cat 1 15 m (5 m green), Cat 2 7.5 m (3 m), Cat 3–5 5 m (3 m); common boundary 3 m incl. 2 m planting verge; floor-to-floor max 5.0 m; average retail unit ≥ 50 m²; corridor 2–2.4 m (single-loaded) / 2.4–3 m (double); covered walkways along road frontage; mixed use: commercial zone ≥ 60 % commercial, C&R zone ≤ 40 % commercial","evidence":"Site plan, sections, unit schedule","ref":"URA DC handbook, Summary-Commercial.pdf","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-URA-27","kind":"rule","scope":"ura","agency":"URA","topic":"URA DC handbook","status":"verified","title":"RC flat roof pavilions","body":"Communal pavilion GFA-exempt up to 50 m² (residential) or 500 m² (B1/commercial) or 50 % of roof coverage, whichever lower; solar panels raised > 1 m (landed) / 1.8 m (others) need permission","evidence":"Roof plan","ref":"URA DC handbook, Summary-FC-v2.pdf; Summary-B1.pdf; Summary-Commercial.pdf","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-HS-01","kind":"rule","scope":"other","agency":"SCDF","topic":"Household Shelter TR 2023","status":"unverified","title":"When required","body":"TR applies to all houses or flats intended as complete and separate private dwelling units; shelter aspects are part of BP and ST submissions from 1 Apr 2023. Statutory trigger and exemptions are in the Civil Defence Shelter Act (not read)","evidence":"HS shown on each unit plan","ref":"Household Shelter TR 2023, Cl. 1.2; BCA BP submission page","src":"https://www.scdf.gov.sg/home/civil-defence-shelter/acts-and-requirements/technical-requirements-for-household-shelters-2023/chapter-2-architectural-requirements"},
{"id":"rule-HS-02","kind":"rule","scope":"other","agency":"SCDF","topic":"Household Shelter TR 2023","status":"web","title":"Minimum size","body":"House GFA ≤ 40 m²: 1.44 m² / 3.6 m³; 40–45: 1.6 / 3.6; 45–75: 2.2 / 5.4; 75–140: 2.8 / 7.2; > 140: 3.4 m² / 9.0 m³","evidence":"HS internal area vs unit GFA","ref":"Household Shelter TR 2023, Cl. 2.2.1(b), Table 2.2.1(b) (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/home/civil-defence-shelter/acts-and-requirements/technical-requirements-for-household-shelters-2023/chapter-2-architectural-requirements"},
{"id":"rule-HS-03","kind":"rule","scope":"other","agency":"SCDF","topic":"Household Shelter TR 2023","status":"web","title":"Dimensions","body":"Internal width ≥ 1200 mm; internal length ≤ 4000 mm; 50 mm increments; max internal area 4.8 m²; clear height 2400–3900 mm","evidence":"HS plan and section dims","ref":"Household Shelter TR 2023, Cl. 2.2.1(a), (d); 2.2.2 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/home/civil-defence-shelter/acts-and-requirements/technical-requirements-for-household-shelters-2023/chapter-2-architectural-requirements"},
{"id":"rule-HS-04","kind":"rule","scope":"other","agency":"SCDF","topic":"Household Shelter TR 2023","status":"web","title":"Wall thickness","body":"By storey height and setback: 250 mm where setback ≤ 6000 mm (storey height ≤ 4 m), else 200 mm; thresholds 7000 / 8000 / 9000 mm for storey heights up to 6 / 8 / 10 m. Non-landed with HS clear height 3000–3200: 275/225; 3200–3900: 300/250. Common wall between HS in cluster housing ≥ 200 mm","evidence":"HS wall thickness on plans","ref":"Household Shelter TR 2023, Cl. 2.3.1, Tables 2.3.1(a)–(b) (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/home/civil-defence-shelter/acts-and-requirements/technical-requirements-for-household-shelters-2023/chapter-2-architectural-requirements"},
{"id":"rule-HS-05","kind":"rule","scope":"other","agency":"SCDF","topic":"Household Shelter TR 2023","status":"web","title":"Slab thickness","body":"Ceiling slab of topmost HS 300 mm (landed 250 mm if RC roof extends over setback); slab between HS 175 mm; floor slab of bottom HS 200 mm; slabs at non-enclosed NS 300 mm","evidence":"HS section","ref":"Household Shelter TR 2023, Cl. 2.3.2–2.3.3 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/home/civil-defence-shelter/acts-and-requirements/technical-requirements-for-household-shelters-2023/chapter-2-architectural-requirements"},
{"id":"rule-HS-06","kind":"rule","scope":"other","agency":"SCDF","topic":"Household Shelter TR 2023","status":"web","title":"Setback from external building line","body":"Table 2.4.3(a) by storey height, e.g. 2500–2800 mm storey: wall with HS door 2750 mm, other walls 2000 mm; 9500–10000 mm storey: 6250 / 5500 mm. Reduced values with RC down-hang beam ≥ 125 mm wide. Intermediate rows not captured","evidence":"Dimension HS walls to external building line","ref":"Household Shelter TR 2023, Cl. 2.4.3–2.4.4 (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/home/civil-defence-shelter/acts-and-requirements/technical-requirements-for-household-shelters-2023/chapter-2-architectural-requirements"},
{"id":"rule-HS-07","kind":"rule","scope":"other","agency":"SCDF","topic":"Household Shelter TR 2023","status":"web","title":"Vertical alignment","body":"HS on every storey directly above the one below, walls continuous to foundation (HS tower); wall of lower HS not thinner than above","evidence":"Stacked unit plans, section","ref":"Household Shelter TR 2023, Cl. 2.4.2(a); 2.3.1(b) (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/home/civil-defence-shelter/acts-and-requirements/technical-requirements-for-household-shelters-2023/chapter-2-architectural-requirements"},
{"id":"rule-HS-08","kind":"rule","scope":"other","agency":"SCDF","topic":"Storey Shelter TR 2021","status":"web","title":"Storey shelter size","body":"Area = total nominal occupancy × 0.6 m²; volume × 1.8 m³; occupancy per unit GFA: ≤ 45 m² 2; 45–75 3; 75–140 4; > 140 5; max 32 m²; width ≥ 1200 mm; staircase SS flight ≥ 1150 mm; clear height 2400–3900 mm","evidence":"SS plan and occupancy calc","ref":"Storey Shelter TR 2021, Cl. 2.2.1–2.2.2 (read from the official web page; spot-check table values)","src":"https://scdf.gov.sg/home/civil-defence-shelter/acts-and-requirements/technical-requirements-for-storey-shelters-2021/chapter-2-architectural-requirements/clause-2.2-size-of-ss"},
{"id":"rule-HS-09","kind":"rule","scope":"other","agency":"SCDF","topic":"Fire Code 2023","status":"web","title":"Fire Code interface","body":"Sprinkler head within 1 m of door of staircase storey shelter on sprinklered floors; storey-shelter exit stair may be mechanically ventilated only where other stairs are naturally ventilated","evidence":"Typical floor fire plan","ref":"Fire Code 2023, FC Cl. 6.4.1f.(1)(c); 9.2.1a.(10)(a) (read from the official web page; spot-check table values)","src":"https://www.scdf.gov.sg/fire-safety-services-listing/fire-code-2023/table-of-content"},
{"id":"rule-NEA-01","kind":"rule","scope":"other","agency":"NEA","topic":"COPEH 2025","status":"verified","title":"Refuse chute","body":"Required for residential buildings (or buildings with residential component) taller than 4 storeys; RC chute cross-section ≥ 0.3 m²; terminate and ventilate at roof","evidence":"Chute on unit/typical floor plan, roof plan","ref":"COPEH 2025, 1.3","src":"https://www.nea.gov.sg/docs/default-source/resource/practices-/copeh-2025.pdf"},
{"id":"rule-NEA-02","kind":"rule","scope":"other","agency":"NEA","topic":"COPEH 2025","status":"verified","title":"Bin point / bin centre","body":"Developments without a refuse room need a bin point or bin centre inside the premises; bin centre mandatory if refuse output > 1,000 litres/day; ≥ 4 m clear height at ingress/egress for refuse vehicle; refuse room roller shutter 3.4 m wide × 4 m high","evidence":"Bin centre on 1st-storey plan, refuse output calc","ref":"COPEH 2025, 1.5(g); 1.6","src":"https://www.nea.gov.sg/docs/default-source/resource/practices-/copeh-2025.pdf"},
{"id":"rule-NEA-03","kind":"rule","scope":"other","agency":"NEA","topic":"COPEH 2025","status":"verified","title":"PWCS","body":"New strata-titled developments with ≥ 500 dwelling units (DA from 1 Apr 2018) need a pneumatic waste conveyance system; bin centre storage ≥ 2 days' output","evidence":"PWCS bin centre","ref":"COPEH 2025, 1.7","src":"https://www.nea.gov.sg/docs/default-source/resource/practices-/copeh-2025.pdf"},
{"id":"rule-NEA-04","kind":"rule","scope":"other","agency":"NEA","topic":"COPEH 2025","status":"unverified","title":"Toilet provision","body":"Sanitary fitting numbers per Appendix 2 by premises type; 1 wash basin per 2 WCs/urinals (min 1); over and above BCA accessible/family provisions. Appendix 2 ratios not extracted","evidence":"Sanitary fitting schedule","ref":"COPEH 2025, 2.2; Appendix 2","src":"https://www.nea.gov.sg/docs/default-source/resource/practices-/copeh-2025.pdf"},
{"id":"rule-PUB-01","kind":"rule","scope":"other","agency":"PUB","topic":"PUB Sewerage COP 3rd Ed.","status":"verified","title":"Sewer setback","body":"Min distance from structure edge (incl. footings/overhangs) to sewer centreline: sewer ≤ 600 mm dia: 1.0 m (depth ≤ 3 m), 1.5 m (3–5 m), 2.0 m (> 5 m); 600–1500 mm: 0.5D + 2.5 m; 1500–2500: 0.5D + 3 m; > 2500: 0.5D + 4 m; DTSS 0.5D + 6 m. No structure over sewers; no manhole inside buildings","evidence":"Site plan with sewer line and setback","ref":"PUB Sewerage COP 3rd Ed., 1.2.4(b), Table 1; 1.2.4(d)","src":"https://www.pub.gov.sg/-/media/PUB/PDF/Code-of-Practice-on-Sewerage-and-Sanitary-Works-3rd-Edition--Mar-2025.pdf"},
{"id":"rule-PUB-02","kind":"rule","scope":"other","agency":"PUB","topic":"PUB Sewerage COP 3rd Ed.","status":"verified","title":"Utilities near sewers","body":"Crossing clearance ≥ 1 m vertical; parallel utilities ≥ 1 m horizontal; drains ≤ 2 m wide may over-cross at ≥ 1 m","evidence":"Services coordination plan","ref":"PUB Sewerage COP 3rd Ed., 1.2.4(c); 1.2.5","src":"https://www.pub.gov.sg/-/media/PUB/PDF/Code-of-Practice-on-Sewerage-and-Sanitary-Works-3rd-Edition--Mar-2025.pdf"},
{"id":"rule-PUB-03","kind":"rule","scope":"other","agency":"PUB","topic":"PUB Surface Water Drainage COP 7th Ed.","status":"unverified","title":"Minimum platform level","body":"Not verified. Search snippets of PUB/URA documents give MPL 4.0 m above SHD (southern coast) / 4.5 m (northern coast) (URA DC16-16 quotes 104.0 / 104.5 mRL), or 300 mm above adjacent road/ground level; critical M&E at or above MPL (Addendum 2). I believe general developments are 300 mm and special facilities 600 mm above adjacent road, but the clause was not seen","evidence":"Site plan platform levels vs road levels","ref":"PUB Surface Water Drainage COP 7th Ed., COPSWD 2.1","src":"https://info.pub.gov.sg/Documents/PUB_COP_7th_Edition.pdf"},
{"id":"rule-PUB-04","kind":"rule","scope":"other","agency":"PUB","topic":"PUB Surface Water Drainage COP 7th Ed.","status":"unverified","title":"Crest level","body":"Not verified. I believe basement/underground entrances need a crest at least 150 mm above MPL (higher for special facilities and those linked to MRT). Clause 2.2 not seen","evidence":"Basement ramp/entrance section levels","ref":"PUB Surface Water Drainage COP 7th Ed., COPSWD 2.2","src":"https://info.pub.gov.sg/Documents/PUB_COP_7th_Edition.pdf"},
{"id":"rule-PUB-05","kind":"rule","scope":"other","agency":"PUB","topic":"PUB Surface Water Drainage COP 7th Ed.","status":"unverified","title":"Detention tank","body":"Not verified. I believe developments ≥ 0.2 ha must limit peak runoff to a runoff coefficient of 0.55 (on-site detention, cl. 7.1.5). The 0.2 ha figure matches the brief but was not seen in a primary source","evidence":"Site area; detention tank on plans","ref":"PUB Surface Water Drainage COP 7th Ed., COPSWD 7.1.5","src":"https://info.pub.gov.sg/Documents/PUB_COP_7th_Edition.pdf"},
{"id":"rule-LTA-01","kind":"rule","scope":"other","agency":"LTA","topic":"LTA Parking COP 2019","status":"verified","title":"Car lot size","body":"2.4 m × 4.8 m; parallel lot 5.4 m long (7.2 m where reversing not possible); lot flat and free of kerbs; lots beside obstructions widened (2.7 m one side / 3.0 m both sides shown in Fig 2.1.1c)","evidence":"Car park plan","ref":"LTA Parking COP 2019, 2.1.1","src":"https://www.lta.gov.sg/content/dam/ltagov/industry_innovations/industry_matters/development_construction_resources/Vehicle_Parking_Proposals/COP_on_Vehicle_Parking_Provision_in_Development_Proposals-2019_Edition.pdf"},
{"id":"rule-LTA-02","kind":"rule","scope":"other","agency":"LTA","topic":"LTA Parking COP 2019","status":"verified","title":"Parking aisle","body":"90°: 6.0 m (1-way) / 6.6 m (2-way); 60°: 4.8 / 6.6 m; 45°: 4.2 m (bays one side) or 4.8 m (two sides) / 6.3 m; 30°: 3.6 or 4.2 / 6.3 m; parallel: 3.6 / 6.0 m","evidence":"Aisle widths","ref":"LTA Parking COP 2019, 2.1.2","src":"https://www.lta.gov.sg/content/dam/ltagov/industry_innovations/industry_matters/development_construction_resources/Vehicle_Parking_Proposals/COP_on_Vehicle_Parking_Provision_in_Development_Proposals-2019_Edition.pdf"},
{"id":"rule-LTA-03","kind":"rule","scope":"other","agency":"LTA","topic":"LTA Parking COP 2019","status":"verified","title":"Ramps and accessways","body":"Straight single lane 3.6 m (3.0 m per lane multi-lane); curved 4.2 m (inside lane 3.6 m, outside 3.3 m multi-lane); inside radius ≥ 4.5 m; gradient 1:10 preferred, 1:8.3 max; parking ramps (sloped floors) 1:25 preferred, 1:20 max","evidence":"Ramp plan/section","ref":"LTA Parking COP 2019, 2.1.3–2.1.4","src":"https://www.lta.gov.sg/content/dam/ltagov/industry_innovations/industry_matters/development_construction_resources/Vehicle_Parking_Proposals/COP_on_Vehicle_Parking_Provision_in_Development_Proposals-2019_Edition.pdf"},
{"id":"rule-LTA-04","kind":"rule","scope":"other","agency":"LTA","topic":"LTA Parking COP 2019","status":"verified","title":"Car park headroom","body":"≥ 2.2 m to underside of beams, signs, sprinklers, fittings","evidence":"Car park section","ref":"LTA Parking COP 2019, 2.1.5","src":"https://www.lta.gov.sg/content/dam/ltagov/industry_innovations/industry_matters/development_construction_resources/Vehicle_Parking_Proposals/COP_on_Vehicle_Parking_Provision_in_Development_Proposals-2019_Edition.pdf"},
{"id":"rule-LTA-05","kind":"rule","scope":"other","agency":"LTA","topic":"LTA Parking COP 2019","status":"verified","title":"Heavy vehicle lots","body":"Rigid < 7.5 m: 7.5 × 3.0 m (9.3 m parallel); rigid > 7.5 m: 12.0 × 3.3 m (14.0 m parallel); articulated: 14.0 × 3.3 m (19.0 m parallel); headroom 4.2 m / 4.2 m / 4.5 m (4.75 m at ramps)","evidence":"Loading bay plans","ref":"LTA Parking COP 2019, 2.2.1","src":"https://www.lta.gov.sg/content/dam/ltagov/industry_innovations/industry_matters/development_construction_resources/Vehicle_Parking_Proposals/COP_on_Vehicle_Parking_Provision_in_Development_Proposals-2019_Edition.pdf"},
{"id":"rule-LTA-06","kind":"rule","scope":"other","agency":"LTA","topic":"LTA Parking COP 2019","status":"unverified","title":"Parking numbers","body":"Provision standards (range-based, by use and zone) are in Chapter 1 / Parking Places Rules – not extracted","evidence":"Lot count table","ref":"LTA Parking COP 2019, Ch. 1","src":"https://www.lta.gov.sg/content/dam/ltagov/industry_innovations/industry_matters/development_construction_resources/Vehicle_Parking_Proposals/COP_on_Vehicle_Parking_Provision_in_Development_Proposals-2019_Edition.pdf"},
{"id":"rule-NPK-01","kind":"rule","scope":"other","agency":"NParks","topic":"URA DC handbook","status":"unverified","title":"Green buffer / planting verge","body":"Widths as per URA tables (URA-07, -19, -23, -26): green buffer 5 m or 3 m inside road buffer; 2 m peripheral planting verge on common boundaries (flats/condos, commercial). NParks handbook v5/v5.1 itself not read","evidence":"Landscape/site plan","ref":"URA DC handbook, URA pages above","src":"https://www.ura.gov.sg/guidelines/development-control/development-control-handbooks/"},
{"id":"rule-NPK-02","kind":"rule","scope":"other","agency":"NParks","topic":"NParks greenery guidelines v5","status":"unverified","title":"Tree conservation","body":"Not verified. I believe approval is needed to fell trees with girth > 1 m in Tree Conservation Areas or on vacant land > 0.4 ha (Parks and Trees Act)","evidence":"Tree survey plan","ref":"NParks greenery guidelines v5, –","src":"https://www.nparks.gov.sg/docs/default-source/resources/2026/guidelines-greenery-provision-tree-conservation-developments-version-5-1.pdf"},
{"id":"rule-SUB-01","kind":"rule","scope":"sheet","agency":"BCA","topic":"","status":"web","title":"BP submission basics","body":"Plans submitted through a QP (registered architect or PE with valid practising certificate) before works commence; URA written permission first; must meet Fifth Schedule performance requirements via AD, COA and TRHS/TRSS","evidence":"QP endorsement on every sheet","ref":"BCA BP submission page: https://www1.bca.gov.sg/safety-and-standards/applications-and-licenses/building-plan-submission/ (read from the official web page; spot-check table values)","src":""},
{"id":"rule-SUB-02","kind":"rule","scope":"sheet","agency":"BCA","topic":"","status":"unverified","title":"Drawing content (site plan, floor plans, sections, elevations, scale, north point)","body":"Not verified. Prescribed in Building Control Regulations 2003 Part II (Application for Approval of Plans); SSO returned 403 so regulation numbers and scales were not seen","evidence":"Sheet index: site plan, all floor plans, roof plan, ≥ 2 sections, all elevations, north point, scale bar, levels, title block","ref":"BC Regs Part II: https://sso.agc.gov.sg/SL/BCA1989-S666-2003?ProvIds=P1II-#P1II-","src":""},
{"id":"rule-SUB-03","kind":"rule","scope":"sheet","agency":"BCA","topic":"CORENET X COP 4th Ed.","status":"unverified","title":"CORENET X","body":"Projects with GFA ≥ 30,000 m² must submit via CORENET X from 1 Oct 2025; others via CORENET 2.0. COP 4th Edition (Sep 2026) effective 1 Jan 2027; BIM in IFC+SG, geo-referenced to SVY21 and SHD; 2D supplementary drawings allowed. Search snippet (not primary): IFC+SG mandatory for GFA ≥ 5,000 m²","evidence":"Model georeference; gateway deliverables","ref":"CORENET X COP 4th Ed., BCA BP page; CX page","src":"https://info.corenet.gov.sg/overview/about-corenet-x/corenet-x-code-of-practice"},
{"id":"rule-SUB-04","kind":"rule","scope":"sheet","agency":"BCA","topic":"","status":"web","title":"BCA lodgment scheme","body":"Ninth Schedule works, e.g. single-storey detached non-residential building with span ≤ 6 m, cantilever ≤ 3 m, height ≤ 6 m, excavation ≤ 2 m; single-level platform ≤ 100 m², ≤ 4 m high","evidence":"Scope check","ref":"https://www1.bca.gov.sg/safety-and-standards/applications-and-licenses/building-plan-submission/lodgment-scheme/ (read from the official web page; spot-check table values)","src":""}]);
